  "info_network.pm1_desc": "Huayue dịch và xuất bản catalogue nhãn hàng TQ sang tiếng Việt, có sẵn cho đại lý in/share cho khách.",
  "info_network.pm2_title": "Hội nghị giới thiệu sản phẩm mới",
  "info_network.pm2_desc": "Tổ chức hằng năm tại Hà Nội & HCM, mời thương hiệu TQ giới thiệu sản phẩm mới, kết nối trực tiếp với BĐS / nhà thầu / công ty thiết kế.",
  "info_network.pm3_title": "Diễn đàn chuyên đề",
  "info_network.pm3_desc": "VLXD thân thiện môi trường, kỹ thuật đồ điện gia dụng, công nghệ gạch porcelain mới — gặp gỡ chuyên gia hai nước.",
  "info_network.pm4_title": "Truyền thông online + offline",
  "info_network.pm4_desc": "Chiến dịch quảng bá thương hiệu TQ trên báo ngành VN, Facebook/Zalo, sự kiện trực tiếp — đưa thương hiệu tiếp cận buyer bản địa.",
  "info_network.pm5_title": "Tour nhà máy Trung Quốc",
  "info_network.pm5_desc": "Đoàn buyer Việt Nam đi thăm nhà máy 2-4 lần/năm: Canton Fair (4 & 10), CIFF (3 & 9), Foshan Pottery (4 & 10). Huayue tổ chức trọn gói.",
  "info_network.tf1_month": "T3",
