  "info_network.tf4_month": "T6",
  "info_network.tf4_desc": "Hội chợ vật liệu xây dựng VN — Huayue mời đoàn nhà máy TQ",
  "info_network.tf5_month": "T9",
  "info_network.tf5_desc": "CIFF session 2 — quy mô lớn hơn Quảng Châu",
